"任何房间": "Ruangan apa pun",
"任何房间：主基地耐久 +{0}%。契合「防御」：守城时 {1} 名陶土守卫加入战斗。": "Ruangan apa pun: ketahanan Benteng +{0}%. Cocok “Pertahanan”: {1} penjaga tanah liat ikut bertahan.",
"任何房间：出征多带 {0} 件宝物。契合「防御」：武器：伤害 +{1}%，命中溅射并减速；其它：再多 {2} 名守卫。": "Ruangan apa pun: bawa {0} relik lebih banyak di ekspedisi. Cocok “Pertahanan”: senjata memberi damage +{1}%, memercik dan memperlambat saat kena; lainnya dapat {2} penjaga tambahan.",
"任何房间：出征带回的物资 +{0}%。契合「运势」：物资再 +{1}%，每场战斗初始积分倍率 +{2}。": "Ruangan apa pun: perbekalan yang dibawa pulang +{0}%. Cocok “Peruntungan”: perbekalan +{1}% lagi, pengali poin awal +{2} tiap pertempuran.",
"任何房间：出征视野 +{0}，初始积分倍率 +{1}。契合「运势 / 特殊」：出征地图一开始就全亮，积分倍率再 +{2}。": "Ruangan apa pun: jarak pandang ekspedisi +{0}, pengali poin awal +{1}. Cocok “Peruntungan / Khusus”: peta ekspedisi terbuka penuh sejak awal, pengali +{2} lagi.",
"任何房间：出征部队攻击 +{0}%。契合「训练」：领袖出征得到的经验 +{1}%。": "Ruangan apa pun: serangan pasukan ekspedisi +{0}%. Cocok “Latihan”: EXP ekspedisi Pemimpin +{1}%.",
"任何房间：出征部队生命 +{0}%。契合「医疗」：医院回复 +{1}%，领袖每天再回 {2}%。": "Ruangan apa pun: HP pasukan ekspedisi +{0}%. Cocok “Medis”: pemulihan rumah sakit +{1}%, pemimpin pulih {2}% lagi per hari.",
"任何房间：图纸掉率 +{0}%。契合「科幻」：基地每天 +{1} 灵魂碎片。": "Ruangan apa pun: peluang drop cetak biru +{0}%. Cocok “Fiksi Ilmiah”: markas +{1} Serpihan Jiwa per hari.",
"任何房间：图纸掉率 +{0}%。契合「锻造」：打造时 {1}% 概率多得一件。": "Ruangan apa pun: peluang drop cetak biru +{0}%. Cocok “Tempa”: {1}% peluang dapat relik tambahan saat menempa.",
"任何房间：基地每天 +{0} 灵魂碎片。契合「魔法」：基地每天再 +{1} 灵魂碎片。": "Ruangan apa pun: markas +{0} Serpihan Jiwa per hari. Cocok “Sihir”: +{1} lagi per hari.",
"任何房间：基地每天 +{0} 物资。契合「后勤」：这个房间自己的效果 ×{1}。": "Ruangan apa pun: markas +{0} perbekalan per hari. Cocok “Logistik”: efek ruangan ini sendiri ×{1}.",
"任何房间：基地每天 +{0} 物资，领袖每天获得 {1} 经验。契合「后勤 / 自然」：这个房间自己的效果 ×{2}。": "Ruangan apa pun: markas +{0} perbekalan per hari, pemimpin dapat {1} EXP per hari. Cocok “Logistik / Alam”: efek ruangan ini sendiri ×{2}.",
"任何房间：宝物打造费用 -{0}%。契合「锻造 / 武器」：锻造：{1}% 概率品质 +{2}；武器：伤害 +{3}%。": "Ruangan apa pun: biaya tempa relik -{0}%. Cocok “Tempa / Senjata”: tempa punya {1}% peluang kualitas +{2}; senjata memberi damage +{3}%.",
"任何房间：建造时间减半，建成返还 {0}% 物资。契合「奇观」：返还提高到 {1}%。": "Ruangan apa pun: waktu bangun separuh, {0}% perbekalan dikembalikan saat selesai. Cocok “Keajaiban”: pengembalian naik jadi {1}%.",
"任何房间：所有防御塔伤害 +{0}%。契合「武器」：射程 +{1}，攻速 +{2}%。": "Ruangan apa pun: semua menara pertahanan memberi damage +{0}%. Cocok “Senjata”: jangkauan +{1}, kecepatan serang +{2}%.",
"任何房间：挖掘费用 -{0}%。契合「特殊」：所有建造少花 {1} 天。": "Ruangan apa pun: biaya galian -{0}%. Cocok “Khusus”: semua pembangunan {1} hari lebih cepat.",
"任何房间：每场战斗初始积分倍率 +{0}。契合「锻造」：打造的宝物品质必定 +{1}。": "Ruangan apa pun: pengali poin awal +{0} tiap pertempuran. Cocok “Tempa”: relik tempaan selalu kualitas +{1}.",
"任何房间：领袖技能冷却少 {0} 个节点。契合「运势」：出征开局多带 {1} 个支援道具（至少转出「史诗」效果）。": "Ruangan apa pun: cooldown skill pemimpin {0} pos lebih singkat. Cocok “Peruntungan”: mulai ekspedisi dengan {1} item bantuan tambahan (minimal efek “Epik”).",
"任何房间：领袖攻击 +{0}%。契合「武器」：伤害 +{1}%，每次攻击放出连锁闪电（跳 {2} 个敌人）。": "Ruangan apa pun: serangan Pemimpin +{0}%. Cocok “Senjata”: damage +{1}%, tiap serangan melepas petir berantai (melompat ke {2} musuh).",
"任何房间：领袖每天回复 {0}% 生命（不需要医院）。契合「医疗 / 水域」：医院回复 +{1}%；水域武器射程 +{2}。": "Ruangan apa pun: pemimpin pulih {0}% HP per hari (tanpa rumah sakit). Cocok “Medis / Perairan”: pemulihan rumah sakit +{1}%; jangkauan senjata air +{2}.",
"任何房间：领袖每天获得 {0} 经验。契合「生产」：这个房间自己的产出 ×{1}。": "Ruangan apa pun: pemimpin dapat {0} EXP per hari. Cocok “Produksi”: hasil ruangan ini sendiri ×{1}.",
"任何房间：领袖每天获得 {0} 经验。契合「训练」：领袖出征得到的经验 +{1}%。": "Ruangan apa pun: pemimpin dapat {0} EXP per hari. Cocok “Latihan”: EXP ekspedisi Pemimpin +{1}%.",
"任何房间：领袖生命 +{0}%。契合「训练」：领袖攻击 +{1}%。": "Ruangan apa pun: HP Pemimpin +{0}%. Cocok “Latihan”: serangan Pemimpin +{1}%.",
