"前面是「墓园」：雾最浓的地方是镇外的墓园，新坟一夜比一夜多。": "Di depan ada “Pemakaman”: kabut paling tebal di sana, dan makam baru bertambah tiap malam.",
"前面是「总装车间」：工厂最后造出来的东西，把工厂里的人都装了进去。": "Di depan ada “Bengkel Perakitan”: benda terakhir buatan pabrik itu memasukkan semua orang pabrik ke dalamnya.",
"前面是「手术室」：院长说手术很成功，病人只是还没醒。": "Di depan ada “Ruang Operasi”: sang direktur bilang operasinya sukses—pasiennya hanya belum bangun.",
"前面是「海底」：港口下面还有一座城，城门是一张嘴。": "Di depan ada “Dasar Laut”: di bawah pelabuhan ada kota lain, dan gerbangnya adalah sebuah mulut.",
"前面是「知识古树」：古树记得森林里发生过的每一件事，它不想再记住别的了。": "Di depan ada “Pohon Pengetahuan”: ia mengingat semua yang pernah terjadi di hutan, dan tak mau mengingat apa-apa lagi.",
"前面是「精灵女王」：女王在月池边等了三百年。她说，你就是她等的那个人。": "Di depan ada “Ratu Elf”: ia menunggu di tepi kolam bulan selama tiga ratus tahun. Katanya, kamulah orang yang ia tunggu.",
"前面是「马戏大棚」：大棚里的笑声从来没停过，只是再也没有观众。": "Di depan ada “Tenda Sirkus”: tawa di dalamnya tak pernah berhenti—hanya saja tak ada lagi penonton.",
